  // API Client errors
  "error.request_timed_out":     { en: "request timed out", zh: "请求超时", fr: "la requête a expiré", es: "la solicitud ha expirado" },
  "error.mast_jwst_failed":     { en: "MAST/JWST search failed before the server returned per-source results. Try again, reduce the search radius, or add SIMBAD to resolve coordinates first.", zh: "MAST/JWST 搜索在服务器返回各源结果之前失败。请重试、缩小搜索半径，或先添加 SIMBAD 解析坐标。", fr: "La recherche MAST/JWST a échoué avant le retour des résultats. Réessayez, réduisez le rayon ou ajoutez SIMBAD.", es: "La búsqueda MAST/JWST falló antes de obtener resultados. Reintente, reduzca el radio o añada SIMBAD." },
  "error.search_failed":        { en: "Search failed before the server returned per-source results. Try again, reduce the search radius, or add SIMBAD / coordinates for name resolution.", zh: "搜索在服务器返回各源结果之前失败。请重试、缩小搜索半径，或添加 SIMBAD / 坐标来解析名称。", fr: "La recherche a échoué avant le retour des résultats. Réessayez, réduisez le rayon ou ajoutez SIMBAD / coordonnées.", es: "La búsqueda falló antes de obtener resultados. Reintente, reduzca el radio o añada SIMBAD / coordenadas." },
  "error.streaming_unsupported": { en: "Streaming not supported by browser", zh: "浏览器不支持流式传输", fr: "Le streaming n'est pas pris en charge par le navigateur", es: "El navegador no admite transmisión en tiempo real" },
  "error.ai_connection_interrupted": { en: "Connection to AI provider was interrupted. This may be a timeout — try a shorter prompt.", zh: "与 AI 提供商的连接中断。可能是超时——请尝试更简短的提示。", fr: "La connexion au fournisseur IA a été interrompue. Essayez un prompt plus court.", es: "La conexión con el proveedor de IA se interrumpió. Intente un prompt más corto." },
  "error.backend_unreachable":   { en: "Could not reach the backend server. Check whether the API service is up.", zh: "无法连接后端服务器。请检查 API 服务是否正在运行。", fr: "Impossible de joindre le serveur backend. Vérifiez que le service API fonctionne.", es: "No se puede conectar al servidor backend. Verifique si el servicio API está activo." },
  // Mid-flight SSE stream drops (client.ts tags these error_class = "stream_drop")
  "error.stream_drop_done_no_reply": { en: "AI reply interrupted — the backend stream ended without returning a final answer or tool results. Please retry; if this keeps happening, start a new chat or shorten the question.", zh: "AI 回复中断 — 后端流已结束，但没有返回最终回答或工具结果。请重试；如果反复出现，请开始一个新聊天或缩短问题。", fr: "Réponse IA interrompue — le flux backend s'est terminé sans réponse finale ni résultats d'outils. Réessayez ; si cela persiste, démarrez une nouvelle discussion ou raccourcissez la question.", es: "Respuesta de IA interrumpida — el flujo del backend terminó sin devolver una respuesta final ni resultados de herramientas. Reintente; si persiste, inicie un chat nuevo o acorte la pregunta." },
  "error.stream_drop_during_tools": { en: "AI reply interrupted — the response stream was closed during tool execution, before a final answer arrived. Please retry; if the tools are already slow, narrow the query.", zh: "AI 回复中断 — 响应流在工具执行过程中被关闭，尚未收到最终回答。请重试；如果工具已经很慢，请缩小查询范围。", fr: "Réponse IA interrompue — le flux a été fermé pendant l'exécution des outils, avant l'arrivée de la réponse finale. Réessayez ; si les outils sont déjà lents, réduisez la portée de la requête.", es: "Respuesta de IA interrumpida — el flujo se cerró durante la ejecución de herramientas, antes de la respuesta final. Reintente; si las herramientas ya son lentas, reduzca el alcance de la consulta." },
  "error.stream_drop_status_only": { en: "AI reply interrupted — the response stream only returned status updates and was closed before any tool call or final answer. Please retry; if this keeps happening, start a new chat or try again later.", zh: "AI 回复中断 — 响应流只返回了状态更新，尚未进入工具调用或最终回答就被关闭。请重试；如果反复出现，请开始一个新聊天或稍后再试。", fr: "Réponse IA interrompue — le flux n'a renvoyé que des mises à jour d'état et a été fermé avant tout appel d'outil ou réponse finale. Réessayez ; si cela persiste, démarrez une nouvelle discussion ou réessayez plus tard.", es: "Respuesta de IA interrumpida — el flujo solo devolvió actualizaciones de estado y se cerró antes de cualquier llamada a herramientas o respuesta final. Reintente; si persiste, inicie un chat nuevo o pruebe más tarde." },
  "error.stream_drop_no_bytes": { en: "AI reply interrupted — the response stream was closed before any content arrived (likely an upstream proxy timeout or a network problem). Please retry; if it recurs, ask a shorter question or try again later.", zh: "AI 回复中断 — 响应流在收到任何内容前被关闭（可能是上游代理超时或网络问题）。请重试；若反复出现，改用更简短的问题或稍后再试。", fr: "Réponse IA interrompue — le flux a été fermé avant l'arrivée de tout contenu (probablement un délai d'attente du proxy en amont ou un problème réseau). Réessayez ; si cela se reproduit, posez une question plus courte ou réessayez plus tard.", es: "Respuesta de IA interrumpida — el flujo se cerró antes de que llegara contenido (probablemente un tiempo de espera del proxy o un problema de red). Reintente; si se repite, use una pregunta más corta o pruebe más tarde." },
  "chat.new_chat_hint": { en: "👉 Use the button below to start a new chat (this clears the current session history):", zh: "👉 点下方按钮开始新聊天（会清空当前会话的历史）：", fr: "👉 Utilisez le bouton ci-dessous pour démarrer une nouvelle discussion (cela efface l'historique de la session en cours) :", es: "👉 Use el botón de abajo para iniciar un chat nuevo (esto borra el historial de la sesión actual):" },

