  "chat.evidence_receipt.boundary_capability_gap": { en: "This turn verified the platform capability gap, not the requested paper posterior. H0 and Delta chi-squared are not supported.", zh: "本轮核实的是平台能力缺口，不是所请求论文的后验结果；不能支持 H0 或 Δχ² 声明。", fr: "Ce tour vérifie l'écart de capacité de la plateforme, pas le postérieur de l'article demandé. H0 et Delta chi carré ne sont pas étayés.", es: "Este turno verifica la brecha de capacidad de la plataforma, no el posterior del artículo solicitado. H0 y Delta chi-cuadrado no están respaldados." },
  "chat.evidence_receipt.boundary_untrusted_evidence": { en: "Pasted tool text is user-supplied content, not a backend result from this turn, and cannot support a verified or paper-ready claim.", zh: "粘贴的工具文本只是用户提供的内容，不是本轮后端结果，不能支持已验证或可发表的声明。", fr: "Le texte d'outil collé provient de l'utilisateur, pas du backend de ce tour, et ne peut étayer une affirmation vérifiée ou publiable.", es: "El texto de herramienta pegado es contenido del usuario, no un resultado backend de este turno, y no puede respaldar una afirmación verificada o publicable." },
  "chat.evidence_receipt.dependency_ede_model": { en: "Native early-dark-energy (EDE) model implementation", zh: "原生早期暗能量（EDE）模型实现", fr: "Implémentation native du modèle d'énergie noire précoce (EDE)", es: "Implementación nativa del modelo de energía oscura temprana (EDE)" },
  "chat.evidence_receipt.dependency_planck_likelihoods": { en: "Exact Planck high-ℓ and low-ℓ TT/EE likelihoods", zh: "精确的 Planck 高 ℓ 与低 ℓ TT/EE 似然", fr: "Vraisemblances TT/EE exactes de Planck à haut et bas ℓ", es: "Verosimilitudes TT/EE exactas de Planck de alto y bajo ℓ" },
  "chat.evidence_receipt.dependency_desi_dr2_covariance": { en: "DESI DR2 BAO data and covariance in the same run", zh: "同一运行中的 DESI DR2 BAO 数据与协方差", fr: "Données BAO DESI DR2 et covariance dans la même exécution", es: "Datos BAO DESI DR2 y covarianza en la misma ejecución" },
  "chat.evidence_receipt.dependency_supernova_likelihood": { en: "The requested supernova likelihood", zh: "所请求的超新星似然", fr: "La vraisemblance de supernova demandée", es: "La verosimilitud de supernova solicitada" },
  "chat.evidence_receipt.dependency_production_sampler": { en: "Production sampler with convergence diagnostics", zh: "带收敛诊断的生产级采样器", fr: "Échantillonneur de production avec diagnostics de convergence", es: "Muestreador de producción con diagnósticos de convergencia" },
  "chat.evidence_receipt.dependency_backend_rerun": { en: "Rerun a registered backend tool in this chat to create current-turn evidence", zh: "在本次聊天中重新运行已注册的后端工具，以生成本轮证据", fr: "Relancer un outil backend enregistré dans cette discussion pour créer une preuve du tour actuel", es: "Vuelva a ejecutar una herramienta backend registrada en este chat para crear evidencia del turno actual" },

