  "home.stat.modules":     { en: "Research modules",   zh: "研究模块",      fr: "Modules de recherche",    es: "Módulos de investigación" },
  "home.stat.tools":       { en: "AI research tools",  zh: "AI 研究工具",   fr: "Outils de recherche IA",  es: "Herramientas IA de investigación" },
